INSERT INTO dictamenes VALUES
(1,'fc65e10e-f9ad-4698-a261-1d03b1212a14'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Papudo: las fuentes de 2015/2017 acreditan el programa superior y su ejecución histórica, pero no una prestación individual ni condiciones actuales. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(23,'69d26871-62e4-435a-a231-35e4d0474262'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. María Elena: consta una línea superior histórica y requisitos de continuidad. No se publica una modalidad de cobertura individual ni una convocatoria actual acreditada. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(68,'b57476f8-6347-4d22-bfb9-86691e11c7ef'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Cholchol: el expediente PADEM acredita antecedentes de 2019–2020. No permite certificar importe, cobertura individual ni condiciones de una convocatoria actual. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(251,'c88b5fa2-cc4a-410b-8d69-8d5975d01409'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Peumo: el aviso municipal de 2025 identifica la beca y documentos de postulación, pero no describe el beneficio económico ni acredita convocatoria actual. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(261,'bbf5e9c1-7545-40a9-800b-4973dd056260'::uuid,2,14,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE IDENTIDAD DEL PROGRAMA. Rauco: el enlace utilizado anteriormente corresponde a Arauco. No acredita la identidad de la candidata original de Rauco; los programas JUNAEB encontrados no sustituyen una beca municipal independiente. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(312,'dc45574b-ef2c-42e6-919f-bc0bf6f308fb'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Toltén: constan antecedentes de 2013 y 2020. La prestación individual y las condiciones de una convocatoria actual no quedan determinadas. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(362,'31ad2b50-30ec-4150-aeed-37ce79d5db6a'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Hualañé: la adjudicación de 2019 acredita un antecedente individual, pero no reglas generales ni cobertura aplicable actualmente. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(393,'e7671aaf-f602-4cf2-bed6-6c0fe63e6165'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. La Florida: consta el título de la Ordenanza 127/2020 para educación superior. No se recuperó su descripción completa del beneficio. La beca escolar de 2026 corresponde a otro nivel. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(402,'0346c14d-e1f7-479e-8d9a-9d4ff17a6d16'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Villa Alemana: la creación presupuestaria para 2025 no acredita por sí sola ejecución, reglas individuales ni cobertura actual del programa superior. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(405,'50d864aa-269c-4ee6-a1eb-b685a8841caf'::uuid,3,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Maipú: identidad, requisitos y fechas de 2026 documentados. El instructivo no acredita importe ni modalidad económica; no se valida un monto procedente solo de prensa. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(412,'f5e0d1a7-69fb-4a5f-8078-b29d69157669'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Pencahue: la nómina municipal de resultados 2026 no publica nivel educativo, beneficio individual ni requisitos de selección. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(426,'f91de4a7-3178-4533-a21c-e8f1ea113fc4'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Viña del Mar: las cuentas de 2022–2023 publican gastos agregados y beneficiarios de educación superior. No determinan importe individual, destino del beneficio ni cobertura actual. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(490,'fa4f6465-132e-4722-aede-f9dd25d63cd7'::uuid,2,14,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE IDENTIDAD DEL PROGRAMA. San Pedro de la Paz: las fuentes incorporadas anteriormente pertenecen a San Pedro de Melipilla. No acreditan el programa de la candidata original; no se trasladan reglas entre comunas. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(500,'a9fc3ffc-dfee-405c-8334-806d65e7c499'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Coronel: la noticia de 2019 acredita entregas universitarias del programa 100 por 100. No publica modalidad individual, reglas generales ni convocatoria actual. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(506,'24dbac8b-a756-4f08-a99e-0e0daa6e382a'::uuid,3,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Maipú: el segundo UUID conserva el mismo alcance documental de 2026. Requisitos y fechas acreditados; importe y modalidad económica no determinados. No se declara duplicidad por compartir fuente. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(510,'c60f68ff-7c99-464e-9179-c7708d743f65'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Calera de Tango: la ficha Social acredita una beca superior sujeta a evaluación. No describe cobertura, modalidad económica ni calendario actual. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(513,'78861a79-69c6-4e9f-9045-fcdfc4f40039'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Cochamó: la cuenta pública de 2025 identifica una beca estudiantil dentro de ayudas sociales. No determina nivel ni cobertura individual; la pista periodística de 2026 no fue corroborada en una fuente municipal accesible. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(514,'03dc06f6-31bc-4f7c-aacb-ba3f09f1eccf'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Cerrillos: la modificación de Ordenanza 20 de 2018 acredita el programa y criterios históricos. No reproduce toda la prestación del texto refundido ni permite certificar una cobertura actual. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.'),
(528,'75c283b9-ad88-47c7-9e36-2a52051dcd98'::uuid,2,13,'DICTAMEN DOCUMENTAL 29/10/2026: INCONCLUSA SOBRE COBERTURA ESPECÍFICA ACTUAL. Viña del Mar: este UUID comparte un rótulo histórico con otra candidata. La cobertura individual sigue sin determinar; no se divide el presupuesto ni se elimina como duplicado sin evidencia suficiente. Se conserva la ficha; esta conclusión no afirma falsedad ni acredita postulaciones abiertas.');
