BEGIN;
SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE dictamenes(id bigint,uuid uuid,version bigint,tipo bigint,texto text) ON COMMIT DROP;
DO $$ BEGIN
 IF (SELECT count(*) FROM becas)<>528 THEN RAISE EXCEPTION 'Inventario diferente'; END IF;
 PERFORM id_beca FROM becas WHERE id_beca IN(SELECT id FROM dictamenes) FOR UPDATE;
 IF EXISTS(SELECT 1 FROM dictamenes d LEFT JOIN becas b ON b.id_beca=d.id WHERE b.id_beca IS NULL OR b.public_id<>d.uuid OR b.version<>d.version OR b.id_tipo_beca<>d.tipo OR b.estado_activa IS DISTINCT FROM false) THEN RAISE EXCEPTION 'Estado previo diferente; conciliar'; END IF;
END $$;
UPDATE becas b SET descripcion_larga=d.texto||E'\n\n'||coalesce(b.descripcion_larga,''),version=b.version+1 FROM dictamenes d WHERE b.id_beca=d.id;
COMMIT;
